"""Private Zabbix classic agent 7.0.32 with bounded framed passive requests."""
import json,os,pathlib,secrets,shutil,signal,socket,struct,subprocess,tempfile,time,zlib

class Rejected(Exception):pass

def free_port():
 for _ in range(64):
  port=20000+secrets.randbelow(10000)
  with socket.socket() as endpoint:
   try:endpoint.bind(('127.0.0.1',port));return port
   except OSError:pass
 raise RuntimeError('private agent port allocation exhausted')

def recv_exact(conn,n):
 out=b''
 while len(out)<n:
  chunk=conn.recv(n-len(out))
  if not chunk:raise Rejected('agent closed the framed request, including source access rejection')
  out+=chunk
 return out

def exchange(port,key,source='127.0.0.1'):
 payload=key.encode('utf8')
 with socket.create_connection(('127.0.0.1',port),timeout=2,source_address=(source,0)) as endpoint:
  endpoint.sendall(b'ZBXD\x01'+struct.pack('<Q',len(payload))+payload)
  try:header=recv_exact(endpoint,5)
  except ConnectionResetError as error:raise Rejected('agent reset the unapproved source') from error
  if header[:4]!=b'ZBXD' or header[4] not in (1,3):raise RuntimeError('unexpected native Zabbix protocol')
  first,second=struct.unpack('<II',recv_exact(endpoint,8))
  if first>1048576 or second>1048576:raise RuntimeError('bounded native frame exceeded')
  raw=recv_exact(endpoint,first)
  return zlib.decompress(raw) if header[4]==3 else raw

